customCommand.command:
printf "%s" "$VOICEINK_TRANSCRIPT" | pbcopy
case "$(lsappinfo info -only bundleid "$(lsappinfo front)")" in
  *'"com.github.wez.wezterm"'*|*'"com.apple.Terminal"'*|*'"com.googlecode.iterm2"'*|*'"com.mitchellh.ghostty"'*|*'"net.kovidgoyal.kitty"'*|*'"org.alacritty"'*) ;;
  *) osascript -e 'tell application "System Events" to keystroke "v" using command down' ;;
esac
